import'dart:io';import'package:flutter/services.dart';
abstract interface class PrinterTransport{Future<void>write(Map<String,dynamic>configuration,Uint8List bytes);}
class LanPrinterTransport implements PrinterTransport{@override Future<void>write(Map<String,dynamic>c,Uint8List bytes)async{final host=c['host']?.toString(),port=int.tryParse(c['port']?.toString()??'')??9100;if(host==null||host.isEmpty)throw StateError('PRINTER_HOST_REQUIRED');final socket=await Socket.connect(host,port,timeout:const Duration(seconds:8));try{socket.add(bytes);await socket.flush();}finally{await socket.close();}}}
class NativePrinterTransport implements PrinterTransport{NativePrinterTransport(this.type);final String type;static const channel=MethodChannel('com.lottivexa/printer');@override Future<void>write(Map<String,dynamic>c,Uint8List bytes)=>channel.invokeMethod<void>('write',{'type':type,'configuration':c,'bytes':bytes});Future<List<Map<String,dynamic>>>discover()async{if(type=='BLUETOOTH'){final allowed=await channel.invokeMethod<bool>('requestBluetoothPermission')??false;if(!allowed)throw StateError('PÈMISYON_BLUETOOTH_REFIZE');}final values=await channel.invokeListMethod<dynamic>('discover',{'type':type})??const[];return values.map((v)=>Map<String,dynamic>.from(v as Map)).toList();}Future<void>openBluetoothSettings()=>channel.invokeMethod<void>('openBluetoothSettings');static Future<void>systemPrint(String text,String businessName)=>channel.invokeMethod<void>('systemPrint',{'text':text,'businessName':businessName});}
